from rules import dependencies, interval


def solve(data):
    packages = data["packages"]
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []) or [])
    names = sorted(packages)
    best = None
    best_score = None
    constraints = {name: interval(spec) for name, spec in roots.items()}

    def is_acyclic(selected_rows):
        graph = {
            name: [dep for dep, _, _ in dependencies(row.get("deps", []), features)]
            for name, row in selected_rows.items()
        }
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dep in graph.get(name, []):
                if not visit(dep):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(assigned, current_constraints, selected_rows):
        nonlocal best, best_score

        for name, version in assigned.items():
            lo, hi = current_constraints[name]
            if (lo is not None and version < lo) or (hi is not None and version > hi):
                return

        pending = sorted(set(current_constraints) - set(assigned))
        if not pending:
            if not is_acyclic(selected_rows):
                return
            score = tuple(assigned.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best = dict(assigned)
            return

        name = pending[0]
        if name not in packages:
            return

        lo, hi = current_constraints[name]
        forbidden = blocked.get(name, ()) or ()
        for row in packages[name]:
            version = row["version"]
            if version in forbidden or (name in pins and version != pins[name]):
                continue
            if (lo is not None and version < lo) or (hi is not None and version > hi):
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_rows = dict(selected_rows)
            next_rows[name] = row
            next_constraints = dict(current_constraints)
            valid = True

            for dep, dep_lo, dep_hi in dependencies(row.get("deps", []), features):
                old_lo, old_hi = next_constraints.get(dep, (None, None))
                new_lo = dep_lo if old_lo is None else old_lo if dep_lo is None else max(old_lo, dep_lo)
                new_hi = dep_hi if old_hi is None else old_hi if dep_hi is None else min(old_hi, dep_hi)
                if new_lo is not None and new_hi is not None and new_lo > new_hi:
                    valid = False
                    break
                next_constraints[dep] = (new_lo, new_hi)

            if valid:
                search(next_assigned, next_constraints, next_rows)

    search({}, constraints, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}

def interval(spec):
    if spec is None:
        return None, None
    if isinstance(spec, dict):
        return spec.get("min"), spec.get("max")
    if isinstance(spec, (list, tuple)):
        lo = spec[0] if len(spec) > 0 else None
        hi = spec[1] if len(spec) > 1 else None
        return lo, hi
    return spec, spec


def dependencies(raw, features=None):
    if raw is None:
        return []

    active_features = set(features or [])
    known = {
        "name", "package", "pkg", "range", "versions", "version_range",
        "min", "max", "version", "feature",
    }
    if isinstance(raw, dict):
        items = [raw] if known.intersection(raw) else list(raw.items())
    elif isinstance(raw, (list, tuple)):
        items = list(raw)
    else:
        items = [raw]

    result = []
    for item in items:
        name = None
        lo = hi = None
        feature = None
        if isinstance(item, str):
            name = item
        elif isinstance(item, dict):
            name = item.get("name", item.get("package", item.get("pkg")))
            feature = item.get("feature")
            if name is None and len(item) == 1:
                name, spec = next(iter(item.items()))
                lo, hi = interval(spec)
                if isinstance(spec, dict):
                    feature = spec.get("feature")
            else:
                spec = item.get("range", item.get("versions", item.get("version_range")))
                if spec is not None:
                    lo, hi = interval(spec)
                elif "min" in item or "max" in item:
                    lo, hi = item.get("min"), item.get("max")
                elif "version" in item:
                    lo = hi = item["version"]
        elif isinstance(item, (list, tuple)) and item:
            name = item[0]
            if len(item) == 2:
                spec = item[1]
                lo, hi = interval(spec)
                if isinstance(spec, dict):
                    feature = spec.get("feature")
            elif len(item) >= 3:
                lo, hi = item[1], item[2]

        if name is not None and (not feature or feature in active_features):
            result.append((name, lo, hi))
    return result
